using System;
using System.Collections.Generic;
using System.Linq;
using System.IO;
using System.Text;
using System.Runtime.Serialization.Json;
using System.Web.Script.Serialization;
namespace DesktopTodo {
 public static class Storage {
  public static readonly string DefaultFolder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DesktopTodo");
  public static string Folder=DefaultFolder;
  public static bool IsTest;
  public static string VaultFolder {get{return IsTest||Folder!=DefaultFolder?Path.Combine(Folder,"Vault"):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"DesktopTodoVault");}}
  public static string SessionFolder {get{return IsTest||Folder!=DefaultFolder?Path.Combine(Folder,"TestProfiles"):Path.Combine(VaultFolder,".profiles");}}
  public static string FilePath {get{return Path.Combine(VaultFolder,"settings.json");}}
  public static string TasksFolder {get{return Path.Combine(VaultFolder,"Tasks");}}
  public static string Diagnostic(){string legacy=Path.Combine(Folder,"data.json");return "User="+System.Security.Principal.WindowsIdentity.GetCurrent().Name+"\nFolder="+Folder+"\nVault="+VaultFolder+"\nProfile="+SessionFolder+"\nLegacyExists="+File.Exists(legacy)+"\nLegacyTasks="+(File.Exists(legacy)?ReadState(legacy).Tasks.Count:-1)+"\nMarkdownTasks="+Directory.GetFiles(TasksFolder,"*.md").Length+"\nLegacyBytes="+(File.Exists(legacy)?new FileInfo(legacy).Length:0);}
  static string baselineRoot="";static Dictionary<string,string> baseline=new Dictionary<string,string>();static Dictionary<string,string> taskPaths=new Dictionary<string,string>();static readonly object gate=new object();static readonly JavaScriptSerializer json=new JavaScriptSerializer();
  static string Canonical(Todo t){using(var stream=new MemoryStream()){new DataContractJsonSerializer(typeof(Todo)).WriteObject(stream,t);return Encoding.UTF8.GetString(stream.ToArray());}}
  static void Prepare(){Directory.CreateDirectory(VaultFolder);Directory.CreateDirectory(TasksFolder);Directory.CreateDirectory(Path.Combine(VaultFolder,"History"));string readme=Path.Combine(VaultFolder,"README.md");if(!File.Exists(readme))File.WriteAllText(readme,"# Desktop Todo local vault\n\nTasks/ contains one Markdown file per task. Front matter stores title, category, due date, important/urgent/done, color and recurrence. The body is the note. Keep the id field unique. You can open this folder in Obsidian.\n\nHistory/ preserves previous versions and deleted tasks. To restore one, copy it back into Tasks/ after checking for duplicate ids. settings.json stores layout and categories, not the authoritative task content.\n\nThis folder is local and outside OneDrive. Login profiles remain in %LOCALAPPDATA%/DesktopTodo/SubscriptionSessions and are never included in task files.\n",new UTF8Encoding(false));if(baselineRoot!=VaultFolder){baselineRoot=VaultFolder;baseline.Clear();taskPaths.Clear();}}
  static State ReadState(string path){using(var stream=File.OpenRead(path)){var value=(State)new DataContractJsonSerializer(typeof(State)).ReadObject(stream);if(value==null||value.Tasks==null||value.Categories==null)throw new InvalidDataException("저장 파일 형식을 확인하세요: "+path);return value;}}
  public static State Load(){lock(gate){Prepare();string legacy=Path.Combine(Folder,"data.json"),marker=Path.Combine(VaultFolder,"legacy-imported.txt");State state=File.Exists(FilePath)?ReadState(FilePath):File.Exists(legacy)?ReadState(legacy):new State();
   // An existing settings file is not evidence that task migration finished.
   if(!File.Exists(marker)&&File.Exists(legacy)){var original=ReadState(legacy);var existing=ReadTasks();var migration=Path.Combine(VaultFolder,"History","migration-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));Directory.CreateDirectory(migration);File.Copy(legacy,Path.Combine(migration,"original-data.json"),false);foreach(var t in original.Tasks)if(!existing.ContainsKey(t.Id))WriteTask(t);Atomic(marker,"Imported local legacy data without overwriting existing Markdown tasks.\n"+DateTime.Now.ToString("O"));}
   var recovery=Path.Combine(VaultFolder,"Recovery");if(Directory.Exists(recovery))foreach(var source in Directory.GetFiles(recovery,"*.json")){if(File.Exists(source+".imported"))continue;var recovered=ReadState(source);var existing=ReadTasks();foreach(var task in recovered.Tasks)if(!existing.ContainsKey(task.Id))WriteTask(task);var verified=ReadTasks();if(recovered.Tasks.Any(t=>!verified.ContainsKey(t.Id)))throw new IOException("복구 파일의 항목을 모두 이전하지 못했습니다. 원본은 보존됩니다.");Atomic(source+".imported","Verified imported task count: "+recovered.Tasks.Count);}
   state.Tasks=ReadTasks().Values.OrderBy(t=>t.Order).ThenBy(t=>t.Date??DateTime.MaxValue).ThenBy(t=>t.Title,StringComparer.Ordinal).ToList();foreach(var category in state.Tasks.Select(t=>t.Category).Distinct())if(!state.Categories.Contains(category))state.Categories.Add(category);state.Migrate();baseline=state.Tasks.ToDictionary(t=>t.Id,Canonical);return state;
  }}
  static Dictionary<string,Todo> ReadTasks(){var tasks=new Dictionary<string,Todo>();var paths=new Dictionary<string,string>();foreach(var file in Directory.GetFiles(TasksFolder,"*.md")){var task=ReadTask(file);if(tasks.ContainsKey(task.Id))throw new InvalidDataException("중복된 할 일 ID입니다. 파일은 보존됩니다: "+file);tasks.Add(task.Id,task);paths[task.Id]=file;}taskPaths=paths;return tasks;}
  static string PathFor(Todo task){Guid id;if(!Guid.TryParse(task.Id,out id))throw new InvalidDataException("할 일 ID는 GUID여야 합니다.");return Path.Combine(TasksFolder,id.ToString()+".md");}
  static void Archive(string path){if(!File.Exists(path))return;var dir=Path.Combine(VaultFolder,"History",DateTime.Now.ToString("yyyy-MM-dd"));Directory.CreateDirectory(dir);File.Copy(path,Path.Combine(dir,DateTime.Now.ToString("HHmmss-fffffff")+"-"+Guid.NewGuid().ToString("N").Substring(0,6)+"-"+Path.GetFileName(path)),false);}
  static void Atomic(string path,string text){string temp=path+".tmp";File.WriteAllText(temp,text,new UTF8Encoding(false));using(var f=new FileStream(temp,FileMode.Open,FileAccess.ReadWrite,FileShare.None))f.Flush(true);if(File.Exists(path))File.Replace(temp,path,path+".bak",true);else File.Move(temp,path);}
  static string ExistingPath(Todo task){string path;return taskPaths.TryGetValue(task.Id,out path)?path:PathFor(task);}
  static void WriteTask(Todo task){string path=ExistingPath(task);string content=ToMarkdown(task);if(File.Exists(path)&&File.ReadAllText(path)==content)return;Archive(path);Atomic(path,content);}
  public static void Save(State state){lock(gate){Prepare();if(state==null||state.Tasks==null||state.Categories==null)throw new InvalidDataException("저장할 데이터가 올바르지 않습니다.");foreach(var task in state.Tasks){DateTime? date;if(!DateRules.TryDate(task.Due,out date))throw new InvalidDataException("마감일 형식을 확인하세요: "+task.Title);}state.Migrate();var desired=state.Tasks.ToDictionary(t=>t.Id,t=>t);var disk=ReadTasks();
   // Detect external edits before changing any file. A layout-only save must never erase task files.
   foreach(var id in baseline.Keys.Union(desired.Keys).Distinct()){string before;baseline.TryGetValue(id,out before);Todo appTask;desired.TryGetValue(id,out appTask);Todo diskTask;disk.TryGetValue(id,out diskTask);string appText=appTask==null?null:Canonical(appTask),diskText=diskTask==null?null:Canonical(diskTask);bool appChanged=appText!=before,diskChanged=diskText!=before;if(appChanged&&diskChanged&&appText!=diskText)throw new IOException("같은 할 일이 외부 파일에서도 변경되었습니다. 로컬 파일은 보존했습니다. 저장소를 다시 불러온 뒤 수정하세요.");}
   foreach(var id in baseline.Keys.Union(desired.Keys).Distinct().ToList()){string before;baseline.TryGetValue(id,out before);Todo task;desired.TryGetValue(id,out task);if((task==null?null:Canonical(task))==before){Todo current;if(task!=null&&disk.TryGetValue(id,out current)&&Canonical(current)==before)disk[id]=task;continue;}if(task!=null){WriteTask(task);disk[id]=task;}else{Todo removed;if(disk.TryGetValue(id,out removed)){string path=ExistingPath(removed);Archive(path);File.Delete(path);disk.Remove(id);}}}
   state.Tasks=state.Tasks.Where(t=>disk.ContainsKey(t.Id)).Select(t=>disk[t.Id]).Concat(disk.Where(pair=>!desired.ContainsKey(pair.Key)).Select(pair=>pair.Value)).ToList();foreach(var c in state.Tasks.Select(t=>t.Category).Distinct())if(!state.Categories.Contains(c))state.Categories.Add(c);
   var settings=new State{Tasks=new List<Todo>(),Categories=state.Categories.ToList(),Subcategories=state.Subcategories.Select(c=>new SubcategoryDefinition{Category=c.Category,Name=c.Name}).ToList(),MainX=state.MainX,MainY=state.MainY,CalendarX=state.CalendarX,CalendarY=state.CalendarY,Width=state.Width,Height=state.Height,Locked=state.Locked,Version=state.Version,Theme=state.Theme};using(var stream=new MemoryStream()){new DataContractJsonSerializer(typeof(State)).WriteObject(stream,settings);Atomic(FilePath,Encoding.UTF8.GetString(stream.ToArray()));}baseline=state.Tasks.ToDictionary(t=>t.Id,Canonical);
  }}
  public static bool HasExternalChanges(){lock(gate){Prepare();var disk=ReadTasks();return disk.Count!=baseline.Count||disk.Any(pair=>!baseline.ContainsKey(pair.Key)||baseline[pair.Key]!=Canonical(pair.Value));}}
  public static Todo Clone(Todo task){using(var stream=new MemoryStream(Encoding.UTF8.GetBytes(Canonical(task))))return (Todo)new DataContractJsonSerializer(typeof(Todo)).ReadObject(stream);}
  public static string ToMarkdown(Todo t){var text=new StringBuilder("---\n");Action<string,object> field=(key,value)=>text.Append(key).Append(": ").Append(json.Serialize(value)).Append('\n');field("id",t.Id);field("title",t.Title);field("category",t.Category);field("subcategory",t.Subcategory);field("due",t.Due);field("priority",t.Priority);field("important",t.Important);field("urgent",t.Urgent);field("done",t.Done);field("color",t.Color);field("repeat",t.Repeat);field("reminder",t.Reminder);field("reminded",t.Reminded);field("completed",t.CompletedAt);field("next_id",t.NextId);field("order",t.Order);text.Append("---\n\n").Append(t.Note??"").Append('\n');return text.ToString();}
  public static Todo ReadTask(string path){string contents=File.ReadAllText(path).Replace("\r\n","\n");if(!contents.StartsWith("---\n"))throw new InvalidDataException("Markdown 앞부분의 메타데이터가 없습니다: "+path);int end=contents.IndexOf("\n---\n",4);if(end<0)throw new InvalidDataException("Markdown 메타데이터 끝을 확인하세요: "+path);var fields=new Dictionary<string,string>();foreach(var line in contents.Substring(4,end-4).Split('\n')){int split=line.IndexOf(':');if(split<1)continue;string key=line.Substring(0,split).Trim(),raw=line.Substring(split+1).Trim();fields[key]=raw.StartsWith("\"")?json.Deserialize<string>(raw):raw;}
   Func<string,string,string> get=(key,fallback)=>fields.ContainsKey(key)?fields[key]:fallback;Func<string,bool> flag=key=>string.Equals(get(key,"false"),"true",StringComparison.OrdinalIgnoreCase);Guid id;if(!Guid.TryParse(get("id",""),out id))throw new InvalidDataException("Markdown ID를 확인하세요: "+path);int priority;double order;var task=new Todo{Id=id.ToString(),Title=get("title",""),Category=get("category","개인"),Subcategory=get("subcategory",""),Due=get("due",""),Priority=int.TryParse(get("priority","1"),out priority)?Math.Max(0,Math.Min(2,priority)):1,Important=flag("important"),Urgent=flag("urgent"),Done=flag("done"),Color=get("color","violet"),Repeat=get("repeat","none"),Reminder=get("reminder",""),Reminded=get("reminded",""),CompletedAt=get("completed",""),NextId=get("next_id",""),Order=double.TryParse(get("order","0"),System.Globalization.NumberStyles.Any,System.Globalization.CultureInfo.InvariantCulture,out order)?order:0,Note=contents.Substring(end+5).TrimStart('\n').TrimEnd('\n')};DateTime? parsedDue;if(!DateRules.TryDate(task.Due,out parsedDue))throw new InvalidDataException("마감일이 올바르지 않습니다: "+path);if(string.IsNullOrWhiteSpace(task.Title))throw new InvalidDataException("제목이 없는 할 일입니다: "+path);return task;}
 }
}
